div.script:

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

let gameState = 'START'; // START, PLAYING, GAMEOVER
let score = 0;
let highscore = parseInt(localStorage.getItem('flappy_eagle_highscore') || '0', 10);

const bird = {
  x: 100,
  y: 360,
  radius: 18,
  gravity: 0.45,
  lift: -8,
  velocity: 0
};

let pipes = [];
let frameCount = 0;
const pipeWidth = 64;
const pipeGap = 180;
const pipeSpeed = 3.2;

function resetGame() {
  bird.y = 360;
  bird.velocity = 0;
  pipes = [];
  score = 0;
  frameCount = 0;
  gameState = 'PLAYING';
}

function jump() {
  if (gameState === 'START' || gameState === 'GAMEOVER') {
    resetGame();
  } else if (gameState === 'PLAYING') {
    bird.velocity = bird.lift;
  }
}

window.addEventListener('keydown', function(e) {
  if (e.code === 'Space' || e.code === 'ArrowUp') {
    e.preventDefault();
    jump();
  }
});

canvas.addEventListener('click', function() {
  jump();
});

function spawnPipe() {
  const minHeight = 80;
  const maxHeight = canvas.height - pipeGap - 120;
  const height = Math.floor(Math.random() * (maxHeight - minHeight + 1)) + minHeight;
  pipes.push({
    x: canvas.width,
    top: height,
    bottom: canvas.height - height - pipeGap,
    passed: false
  });
}

function update() {
  if (gameState !== 'PLAYING') return;

  bird.velocity += bird.gravity;
  bird.y += bird.velocity;

  // Floor and ceiling collision
  if (bird.y + bird.radius >= canvas.height - 40) {
    bird.y = canvas.height - 40 - bird.radius;
    gameOver();
  }
  if (bird.y - bird.radius <= 0) {
    bird.y = bird.radius;
    bird.velocity = 0;
  }

  // Pipe spawning
  frameCount++;
  if (frameCount % 90 === 0) {
    spawnPipe();
  }

  // Pipe movement & collision
  for (let i = pipes.length - 1; i >= 0; i--) {
    pipes[i].x -= pipeSpeed;

    // Check collision
    if (
      bird.x + bird.radius > pipes[i].x &&
      bird.x - bird.radius < pipes[i].x + pipeWidth &&
      (bird.y - bird.radius < pipes[i].top || bird.y + bird.radius > canvas.height - pipes[i].bottom)
    ) {
      gameOver();
    }

    // Score update
    if (!pipes[i].passed && pipes[i].x + pipeWidth < bird.x) {
      score++;
      pipes[i].passed = true;
      if (score > highscore) {
        highscore = score;
        localStorage.setItem('flappy_eagle_highscore', highscore);
      }
    }

    // Remove off-screen pipes
    if (pipes[i].x + pipeWidth < 0) {
      pipes.splice(i, 1);
    }
  }
}

function gameOver() {
  gameState = 'GAMEOVER';
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Background stars / clouds simulation
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw Pipes
  for (let i = 0; i < pipes.length; i++) {
    ctx.fillStyle = '#38bdf8';
    // Top pipe
    ctx.fillRect(pipes[i].x, 0, pipeWidth, pipes[i].top);
    // Bottom pipe
    ctx.fillRect(pipes[i].x, canvas.height - pipes[i].bottom, pipeWidth, pipes[i].bottom);
  }

  // Draw Ground
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(0, canvas.height - 40, canvas.width, 40);
  ctx.fillStyle = '#38bdf8';
  ctx.fillRect(0, canvas.height - 44, canvas.width, 4);

  // Draw Bird
  ctx.beginPath();
  ctx.arc(bird.x, bird.y, bird.radius, 0, Math.PI * 2);
  ctx.fillStyle = '#facc15';
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = '#f8fafc';
  ctx.stroke();
  ctx.closePath();

  // Bird Eye / Beak details
  ctx.beginPath();
  ctx.arc(bird.x + 6, bird.y - 4, 3, 0, Math.PI * 2);
  ctx.fillStyle = '#0f172a';
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(bird.x + bird.radius, bird.y);
  ctx.lineTo(bird.x + bird.radius + 8, bird.y + 3);
  ctx.lineTo(bird.x + bird.radius, bird.y + 6);
  ctx.fillStyle = '#f97316';
  ctx.fill();

  // UI / Text
  if (gameState === 'START') {
    ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#38bdf8';
    ctx.font = '900 36px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText('FLAPPY EAGLE', canvas.width / 2, canvas.height / 2 - 40);
    ctx.fillStyle = '#f8fafc';
    ctx.font = '600 16px system-ui';
    ctx.fillText('Press Spacebar or Click to Jump', canvas.width / 2, canvas.height / 2 + 10);
    ctx.fillStyle = '#facc15';
    ctx.fillText('High Score: ' + highscore, canvas.width / 2, canvas.height / 2 + 60);
  } else if (gameState === 'PLAYING') {
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 48px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText(score, canvas.width / 2, 80);
  } else if (gameState === 'GAMEOVER') {
    ctx.fillStyle = 'rgba(15, 23, 42, 0.9)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ef4444';
    ctx.font = '900 40px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 50);
    ctx.fillStyle = '#f8fafc';
    ctx.font = '700 20px system-ui';
    ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2);
    ctx.fillStyle = '#facc15';
    ctx.fillText('High Score: ' + highscore, canvas.width / 2, canvas.height / 2 + 40);
    ctx.fillStyle = '#38bdf8';
    ctx.font = '600 16px system-ui';
    ctx.fillText('Click or Press Space to Restart', canvas.width / 2, canvas.height / 2 + 100);
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
